<?php
namespace Cyberfort\AIRegister; defined( 'ABSPATH' ) || exit;
class Shortcodes { public function init(): void { add_shortcode( 'cyberfort_ai_register', [ $this, 'register' ] ); add_shortcode( 'cyberfort_ai_system', [ $this, 'system' ] ); } public function register( $atts = [] ): string { $atts = shortcode_atts( [ 'language' => 'auto', 'layout' => 'cards', 'search' => 'yes', 'filters' => 'yes', 'per_page' => 12 ], $atts, 'cyberfort_ai_register' ); return ( new Renderer() )->register( [ 'language' => in_array( $atts['language'], [ 'auto', 'lv', 'en' ], true ) ? $atts['language'] : 'auto', 'layout' => 'list' === $atts['layout'] ? 'list' : 'cards', 'search' => 'yes' === $atts['search'], 'filters' => 'yes' === $atts['filters'], 'per_page' => min( 50, max( 1, absint( $atts['per_page'] ) ) ) ] ); } public function system( $atts = [] ): string { $atts = shortcode_atts( [ 'reference' => '', 'language' => 'auto' ], $atts, 'cyberfort_ai_system' ); return ( new Renderer() )->system( sanitize_text_field( $atts['reference'] ), $atts['language'] ); } }
